import {state,esc,totalProgress,minutes,fmt,dateKey,currentProfile} from '../../lib/store.js';import {panel,bar,icon,button,badge,empty} from '../pixel/primitives.js';
export const destinations=[['home','CONTROL ROOM','总控制台'],['research','RESEARCH LAB','论文研究所'],['training','TRAINING NETWORK','葡语训练中心'],['focus','FOCUS CHAMBER','专注舱'],['vault','DATA VAULT','资料中心'],['life','LIFE LOG','生活公寓'],['mission','MISSION CONTROL','任务管理中心']];
export function taskList(filter=false){const list=state.tasks.filter(t=>!filter||t.cat==='论文');return list.map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" id="task-${t.id}" data-change="task" data-id="${t.id}" ${t.done?'checked':''}><label for="task-${t.id}">${esc(t.text)}</label><span class="badge">${esc(t.cat)}</span><button data-action="delete-task" data-id="${t.id}" aria-label="删除任务 ${esc(t.text)}">×</button></div>`).join('')+`<form class="inline-form" data-form="task"><input name="text" required maxlength="160" aria-label="新任务" placeholder="输入下一步行动…">${filter?'<input type="hidden" name="cat" value="论文">':'<select name="cat" aria-label="任务类别"><option>论文</option><option>葡语</option><option>翻译</option><option>生活</option></select>'}<button class="button primary">＋ 添加</button></form>`}
export function city(){return `<section class="world" aria-label="可交互的像素赛博城市地图"><canvas id="scene" aria-label="原创像素城市夜景" role="img"></canvas><div class="rain" aria-hidden="true"></div><div class="world-title"><div class="eyebrow">SECTOR 07 / PERSONAL DISTRICT</div><h1>WELCOME HOME<span class="cursor">_</span></h1><p>欢迎回来，${esc(currentProfile()?.displayName||'Guest')}。你的城市，正在运行。</p></div><div class="district-code">double's home<br><span class="muted">LOCAL-ONLY UNIVERSE</span></div>${destinations.slice(1).map(([id,en,zh],i)=>`<button class="map-point" data-action="navigate" data-destination="${id}" data-value="${id}">${icon(id,16)} ${en}<small>${String(i+1).padStart(2,'0')} / ${zh}</small></button>`).join('')}<div class="map-footer"><span>SELECT A DISTRICT TO ENTER</span><span>LOCAL PROFILE / PRIVATE RECORDS</span></div></section>`}
export function home(){const remaining=state.tasks.filter(t=>!t.done),mood=state.moods[dateKey()],days=Math.max(0,Math.ceil((new Date(state.deadline+'T23:59:59')-new Date())/86400000));return `<div class="page home"><div class="row mb"><div class="eyebrow" style="margin:0">CONTROL ROOM / DAILY HUD</div><span class="micro muted">${dateKey()} · 本地存档</span></div><div class="stats mb"><div class="stat"><span class="label">TODAY QUESTS / 今日任务</span><div class="value">${remaining.length} LEFT</div><span class="micro muted">${state.tasks.length-remaining.length} / ${state.tasks.length} 已完成</span></div><div class="stat"><span class="label">FOCUS / 今日专注</span><div class="value">${fmt(minutes('today'))}</div><a href="#focus" class="small">进入专注舱 →</a></div><div class="stat"><span class="label">PORTUGUESE / 今日训练</span><div class="value" style="color:var(--magenta)">${state.trainingDays.includes(dateKey())?'DONE':'READY'}</div><a href="#training" class="small">C1 今日葡语 →</a></div><div class="stat"><span class="label">WEATHER / ${esc(state.weather?.city||'未设置城市')}</span><div class="value" style="color:var(--orange)">${state.weather?Math.round(state.weather.current.temperature_2m)+'°C':'--°C'}</div><a href="#life" class="small">${state.weather?'查看天气与更新时间':'选择城市，启用天气'} →</a></div></div><div class="grid"><div class="stack">${panel('MAIN QUEST / MASTER THESIS',`<div class="row"><span class="badge magenta">LV.02 / RESEARCHER</span><span class="micro muted">示例课题 · 可编辑</span></div><h3>${esc(state.thesisTitle)}</h3><p class="muted small">当前优先：${esc(remaining.find(t=>t.cat==='论文')?.text||'论文任务全部完成')}</p><div class="row"><span class="micro muted">TOTAL PROGRESS</span><span class="big-number">${totalProgress()}%</span></div>${bar(totalProgress(),'论文进度','magenta')}<div class="row"><span class="small muted">DEADLINE / ${state.deadline}</span><a href="#research" class="button magenta">进入研究所 →</a></div>`,'','quest')}${panel('TODAY QUESTS',taskList(),badge(remaining.length+' 待完成','cyan'))}</div><div class="stack">${panel('COUNTDOWN.exe',`<div class="row"><div><div class="big-number" style="color:var(--orange)">${days}<span class="micro"> DAYS</span></div><p class="small muted">论文截止 · ${state.deadline}</p></div>${icon('focus',44)}</div><a href="#research" class="small">调整日期 →</a>`)}${panel('MOOD.exe',`<div class="row"><div><h3>${mood?esc(mood.mood):'今天的你，还好吗？'}</h3><p class="small muted">${mood?'ENERGY '+mood.energy+'/10 · '+esc(mood.note):'给今天留一个小小的注脚。'}</p></div>${icon(mood?'happy':'life',30)}</div><a href="#life" class="small">${mood?'查看生活记录':'记录今日心情'} →</a>`)}${panel('RECENT READING',state.papers.slice(0,2).map(p=>`<div class="listrow">${icon('training')}<div class="content"><h3>${esc(p.title)}</h3><p>${esc(p.author)} · ${esc(p.status)}</p></div><button class="button small" data-action="paper-edit" data-id="${p.id}">阅读笔记</button></div>`).join(''))}</div></div></div>`}
